// Accel-net usability gtest against the stable exported reference arrays.
//
// Stable exports (output/learn/, generated by script/learn/accel_net.py
// --finalize-export) are the authority:
//   accel_net_weights.npz     W1(64,14),b1,W2(64,64),b2,W3(3,64),b3 (float64,
//                             PyTorch Linear row-major layout) + constants;
//   accel_net_ref.npz         128 x {q,t_abs,features,out};
//   accel_net_gve_ref.npz     qdot_base = gveRhsField(q,t,beta),
//                             qdot_field = qdot_base + W @ a_field (a_field is
//                             the network output used directly in ECI, no RTN);
//   accel_net_isl_ref.npz     4 stars / 4 edges / one frame ISL reference:
//                             d, dobs, residual, cost, grad;
//   accel_net_scripted.pt     float64 TorchScript of the same MLP.
//
// Covers: (1) Eigen MLP (float64 npz weights) vs reference features/out;
// (2) CPU no-grad / InferenceMode latency, no autograd graph; (3) QOE
// perturbation <=10 m / 0.1 m/s with measured p99.9 / no isolated jump;
// (4) GVE RHS superposition against the reference (base + W @ a_field);
// (5) ISL d/dobs/residual/cost/grad against the reference; (6) a small
// 4-star fixed-module ISL optimization (cost decreases, loop stays finite).
// No src/kernel edits; no window/45T.
#include <gtest/gtest.h>
#include <Eigen/Dense>
#include <torch/script.h>
