// ---- minimal stored-npz reader (np.savez, ZIP_STORED; numeric .npy) ----
struct NpzArray {
    std::vector<long long> shape;
    std::vector<double> data;
    long long count() const {
        long long n = 1;
        for (long long d : shape) n *= d;
        return n;
    }
    long long dim(int i) const { return shape.empty() ? 1 : shape[i]; }
};

class NpzReader {
public:
    explicit NpzReader(const std::string &path) { load(path); }
    const NpzArray &at(const std::string &name) const {
        auto it = m_.find(name);
        if (it == m_.end()) throw std::runtime_error("npz key missing: " + name);
        return it->second;
    }
    bool has(const std::string &name) const { return m_.count(name) != 0; }

private:
    std::map<std::string, NpzArray> m_;
    static uint16_t u16(const unsigned char *p) { uint16_t v; std::memcpy(&v, p, 2); return v; }
    static uint32_t u32(const unsigned char *p) { uint32_t v; std::memcpy(&v, p, 4); return v; }
    static std::string trim(const std::string &s) {
        const auto a = s.find_first_not_of(" \t\r\n");
        const auto b = s.find_last_not_of(" \t\r\n");
        return a == std::string::npos ? std::string() : s.substr(a, b - a + 1);
    }
    void parse_npy(const std::string &name, const unsigned char *p, size_t n) {
        if (n < 10 || std::memcmp(p, "\x93NUMPY", 6) != 0) throw std::runtime_error("bad npy " + name);
        const int major = p[6];
        size_t hlen, off;
        if (major == 1) { hlen = u16(p + 8); off = 10; }
        else { hlen = u32(p + 8); off = 12; }
        const std::string hdr((const char *)p + off, hlen);
        size_t dpos = hdr.find("descr");
        if (dpos == std::string::npos) throw std::runtime_error("npy descr " + name);
        const size_t dcolon = hdr.find(':', dpos);
        const size_t q1 = hdr.find_first_of("'\"", dcolon);
        const size_t q2 = hdr.find_first_of("'\"", q1 + 1);
        if (dcolon == std::string::npos || q1 == std::string::npos || q2 == std::string::npos)
            throw std::runtime_error("npy descr value " + name);
        const std::string descr = hdr.substr(q1 + 1, q2 - q1 - 1);
        if (descr.find("f8") == std::string::npos && descr.find("i8") == std::string::npos &&
            descr.find("f4") == std::string::npos)
            return;   // strings/objects/metadata: not needed by this test
        size_t fpos = hdr.find("fortran_order");
        if (fpos != std::string::npos) {
            const size_t fcolon = hdr.find(':', fpos);
            const size_t tpos = hdr.find("True", fcolon);
            if (tpos != std::string::npos && tpos - fcolon < 12)
                throw std::runtime_error("fortran-order npy " + name);
        }
        std::vector<long long> shape;
        size_t spos = hdr.find("shape");
        if (spos != std::string::npos) {
            size_t a = hdr.find('(', spos), b = hdr.find(')', a);
            if (a != std::string::npos && b != std::string::npos) {
                std::stringstream ss(hdr.substr(a + 1, b - a - 1));
                std::string tok;
                while (std::getline(ss, tok, ',')) {
                    tok = trim(tok);
                    if (!tok.empty()) shape.push_back(std::stoll(tok));
                }
            }
        }
        NpzArray arr;
        arr.shape = shape;
        const long long cnt = arr.count();
        const size_t dsz = descr.find("f4") != std::string::npos ? 4 : 8;
        const unsigned char *d = p + off + hlen;
        const size_t avail = n > off + hlen ? n - off - hlen : 0;
        if ((size_t)cnt * dsz > avail) throw std::runtime_error("npy size " + name);
        arr.data.resize((size_t)cnt);
        for (long long k = 0; k < cnt; ++k) {
            if (descr.find("f8") != std::string::npos) {
                double v; std::memcpy(&v, d + k * 8, 8); arr.data[(size_t)k] = v;
            } else if (descr.find("i8") != std::string::npos) {
                int64_t v; std::memcpy(&v, d + k * 8, 8); arr.data[(size_t)k] = (double)v;
            } else {
                float v; std::memcpy(&v, d + k * 4, 4); arr.data[(size_t)k] = v;
            }
        }
        m_[name] = std::move(arr);
    }
    void load(const std::string &path) {
        std::ifstream f(path, std::ios::binary | std::ios::ate);
        if (!f) throw std::runtime_error("npz open: " + path);
        const std::streamsize sz = f.tellg();
        f.seekg(0);
        std::vector<unsigned char> buf((size_t)sz);
        f.read((char *)buf.data(), sz);
        if (!f) throw std::runtime_error("npz read: " + path);
        const long long n = (long long)buf.size();
        long long eocd = -1;
        for (long long i = n - 22; i >= 0 && i >= n - 65557; --i)
            if (u32(buf.data() + i) == 0x06054b50u) { eocd = i; break; }
        if (eocd < 0 || eocd + 22 > n) throw std::runtime_error("npz EOCD: " + path);
        const int nent = (int)u16(buf.data() + eocd + 10);
        long long p = (long long)u32(buf.data() + eocd + 16);
        for (int e = 0; e < nent; ++e) {
            if (p < 0 || p + 46 > n || u32(buf.data() + p) != 0x02014b50u)
                throw std::runtime_error("npz CD: " + path);
            const int method = (int)u16(buf.data() + p + 10);
            const uint32_t usize = u32(buf.data() + p + 24);
            const int nlen = (int)u16(buf.data() + p + 28), elen = (int)u16(buf.data() + p + 30),
                      clen = (int)u16(buf.data() + p + 32);
            const long long lo = (long long)u32(buf.data() + p + 42);
            std::string name((const char *)buf.data() + p + 46, nlen);
            p += 46 + nlen + elen + clen;
            if (method != 0 || name.size() < 5 || name.substr(name.size() - 4) != ".npy") continue;
            if (lo < 0 || lo + 30 > n || u32(buf.data() + lo) != 0x04034b50u)
                throw std::runtime_error("npz LH: " + path);
            const int ln = (int)u16(buf.data() + lo + 26), le = (int)u16(buf.data() + lo + 28);
            const long long dpos = lo + 30 + ln + le;
            parse_npy(name.substr(0, name.size() - 4), buf.data() + dpos, usize);
        }
    }
};

constexpr double kMuAccel = 3.986004415e14;

// ---- spec constants (output/learn/accel_net_spec.json) ----
constexpr double kARef = 7.0e6;
constexpr double kIRef = 1.265363707695889;     // deg2rad(72.5)
constexpr double kOmegaEarth = 7.2921159e-5;
constexpr double kTDay = 86400.0;
constexpr double kT = 5760.0;
constexpr double kSlowT = 5.0 * kT;             // 28800
constexpr double kTIsl0 = 23673600.0;
constexpr double kAScale = 1e-6;
constexpr int kFeat = 14, kHidden = 64, kOut = 3;

double silu(double x) { return x / (1.0 + std::exp(-x)); }

double wrap_pi(double x) {
    double y = std::fmod(x + M_PI, 2.0 * M_PI);
    if (y < 0.0) y += 2.0 * M_PI;
    return y - M_PI;
}

Eigen::Matrix<double, kFeat, 1> features(const Vector6d &q, double t_abs,
                                          double t_isl0 = kTIsl0) {
    const double a = q[0], u = q[1], ex = q[2], ey = q[3], inc = q[4], Om = q[5];
    double td = std::fmod(t_abs, kTDay);
    if (td < 0.0) td += kTDay;
    const double thetaG = kOmegaEarth * td;
    const double lt = wrap_pi(Om + u - thetaG);
    Eigen::Matrix<double, kFeat, 1> f;
    f << a / kARef - 1.0, std::cos(u), std::sin(u), ex, ey, inc - kIRef,
         std::cos(Om), std::sin(Om), std::cos(thetaG), std::sin(thetaG),
         std::cos(lt), std::sin(lt), (t_abs - t_isl0) / kSlowT,
         td / kTDay - 0.5;
    return f;
}

// ---- Eigen MLP loaded from the float64 npz (PyTorch Linear row-major) ----
struct MlpWeights {
    Eigen::Matrix<double, kHidden, kFeat, Eigen::RowMajor> w1;
    Eigen::Matrix<double, kHidden, 1> b1;
    Eigen::Matrix<double, kHidden, kHidden, Eigen::RowMajor> w2;
    Eigen::Matrix<double, kHidden, 1> b2;
    Eigen::Matrix<double, kOut, kHidden, Eigen::RowMajor> w3;
    Eigen::Matrix<double, kOut, 1> b3;
    double a_scale = kAScale;

    MlpWeights() = default;
    static void must(const NpzArray &a, long long n, const char *what) {
        if (a.count() != n)
            throw std::runtime_error(std::string("npz shape mismatch: ") + what);
    }
    explicit MlpWeights(const std::string &path) {
        NpzReader z(path);
        const auto &W1 = z.at("W1");
        must(W1, (long long)kHidden * kFeat, "W1(64,14)");
        std::memcpy(w1.data(), W1.data.data(), sizeof(double) * (size_t)W1.count());
        const auto &B1 = z.at("b1");
        must(B1, kHidden, "b1(64)");
        std::memcpy(b1.data(), B1.data.data(), sizeof(double) * kHidden);
        const auto &W2 = z.at("W2");
        must(W2, (long long)kHidden * kHidden, "W2(64,64)");
        std::memcpy(w2.data(), W2.data.data(), sizeof(double) * (size_t)W2.count());
        const auto &B2 = z.at("b2");
        must(B2, kHidden, "b2(64)");
        std::memcpy(b2.data(), B2.data.data(), sizeof(double) * kHidden);
        const auto &W3 = z.at("W3");
        must(W3, (long long)kOut * kHidden, "W3(3,64)");
        std::memcpy(w3.data(), W3.data.data(), sizeof(double) * (size_t)W3.count());
        const auto &B3 = z.at("b3");
        must(B3, kOut, "b3(3)");
        std::memcpy(b3.data(), B3.data.data(), sizeof(double) * kOut);
        a_scale = z.at("a_scale").data[0];
    }

    Eigen::Matrix<double, kOut, 1> operator()(const Eigen::Matrix<double, kFeat, 1> &f) const {
        Eigen::Matrix<double, kHidden, 1> h1 = w1 * f + b1;
        for (int i = 0; i < kHidden; ++i) h1[i] = silu(h1[i]);
        Eigen::Matrix<double, kHidden, 1> h2 = w2 * h1 + b2;
        for (int i = 0; i < kHidden; ++i) h2[i] = silu(h2[i]);
        return (w3 * h2 + b3) * a_scale;
    }
};

