std::vector<Vector6d> to_v6(const NpzArray &a) {
    std::vector<Vector6d> v((size_t)(a.count() / 6));
    for (size_t i = 0; i < v.size(); ++i)
        for (int c = 0; c < 6; ++c) v[i][c] = a.data[i * 6 + c];
    return v;
}

std::mt19937_64 rng(20261101);
std::uniform_real_distribution<double> uni(0.0, 1.0);

Vector6d random_q() {
    Vector6d q;
    q[0] = kARef * (1.0 + 0.01 * (uni(rng) - 0.5));
    q[1] = -M_PI + 2.0 * M_PI * uni(rng);
    q[2] = 2e-3 * (uni(rng) - 0.5);
    q[3] = 2e-3 * (uni(rng) - 0.5);
    q[4] = kIRef + 0.05 * (uni(rng) - 0.5);
    q[5] = -M_PI + 2.0 * M_PI * uni(rng);
    return q;
}

double random_t() { return kTIsl0 + 5.0 * kT * uni(rng); }

// ---- TorchScript float64 module (accel_net_scripted.pt) ----
struct TorchMlp {
    torch::jit::Module mod;
    explicit TorchMlp(const std::string &path) : mod(torch::jit::load(path)) { mod.eval(); }
    torch::Tensor ts(const torch::Tensor &x, bool nograd) {
        if (nograd) {
            torch::NoGradGuard ng;
            return mod.forward({x}).toTensor();
        }
        return mod.forward({x}).toTensor();
    }
};

torch::Tensor to_ts64(const Eigen::Matrix<double, Eigen::Dynamic, kFeat> &F) {
    std::vector<double> h((size_t)F.rows() * kFeat);
    for (int i = 0; i < F.rows(); ++i)
        for (int j = 0; j < kFeat; ++j) h[(size_t)i * kFeat + j] = F(i, j);
    return torch::from_blob(h.data(), {F.rows(), kFeat},
                            torch::TensorOptions().dtype(torch::kFloat64)).clone();
}

torch::Tensor torch_features(torch::Tensor q, const torch::Tensor &t_abs) {
    auto a = q.select(1, 0), u = q.select(1, 1), ex = q.select(1, 2),
         ey = q.select(1, 3), inc = q.select(1, 4), Om = q.select(1, 5);
    auto tt = t_abs.expand({q.size(0)});
    auto td = torch::remainder(tt, kTDay);
    auto thetaG = kOmegaEarth * td;
    auto lt = torch::remainder(Om + u - thetaG + M_PI, 2.0 * M_PI) - M_PI;
    return torch::stack({a / kARef - 1.0, torch::cos(u), torch::sin(u), ex, ey,
                         inc - kIRef, torch::cos(Om), torch::sin(Om),
                         torch::cos(thetaG), torch::sin(thetaG),
                         torch::cos(lt), torch::sin(lt),
                         (tt - kTIsl0) / kSlowT, td / kTDay - 0.5}, 1);
}

