Eigen::Matrix<double, 6, 6> rv_jac_fd(const Vector6d &q) {
    const double eps[6] = {1e-1, 1e-7, 1e-7, 1e-7, 1e-7, 1e-7};
    Eigen::Matrix<double, 6, 6> J;
    for (int c = 0; c < 6; ++c) {
        Vector6d qp = q, qm = q;
        qp[c] += eps[c]; qm[c] -= eps[c];
        J.col(c) = (noeOsc2rv(qp, 100, 1e-12) - noeOsc2rv(qm, 100, 1e-12)) /
                   (2.0 * eps[c]);
    }
    return J;
}

std::vector<Vector6d> data_qoe() {
    std::vector<Vector6d> qs;
    for (int r = 0; r < 6; ++r) {
        Eigen::VectorXd rv(6);
        for (int i = 0; i < 6; ++i) rv[i] = kDataRv[r][i];
        const Eigen::VectorXd q = osculating::rv2OEOsc(rv);
        Vector6d qv;
        for (int i = 0; i < 6; ++i) qv[i] = q[i];
        qs.push_back(qv);
    }
    return qs;
}

double pct(std::vector<double> v, double p) {
    if (v.empty()) return 0.0;
    std::sort(v.begin(), v.end());
    size_t k = (size_t)std::floor(p * (double)(v.size() - 1));
    return v[std::min(k, v.size() - 1)];
}

