// 1) Eigen MLP (float64 npz weights) vs the stable reference features / out.
TEST(AccelNet, InferenceVsReference) {
    const std::string wp = learn_file("accel_net_weights.npz");
    const std::string rp = learn_file("accel_net_ref.npz");
    ASSERT_FALSE(wp.empty()) << "accel_net_weights.npz not found";
    ASSERT_FALSE(rp.empty()) << "accel_net_ref.npz not found";
    MlpWeights mlp;
    ASSERT_NO_THROW(mlp = MlpWeights(wp));
    NpzReader ref(rp);
    const auto &Q = ref.at("q"), &T = ref.at("t_abs"), &Fref = ref.at("features"),
               &Oref = ref.at("out");
    const int N = (int)Q.dim(0);
    ASSERT_EQ(N, 128);
    ASSERT_EQ(Fref.count(), (long long)N * kFeat);
    ASSERT_EQ(Oref.count(), (long long)N * kOut);
    const double t_isl0 = ref.at("t_isl0").data[0];
    double max_feat = 0.0, max_out_own = 0.0, max_out_ref = 0.0, out_scale = 0.0;
    std::ofstream c(csv_path("accel_net_infer.csv"));
    c << "sample,max_abs_feature,max_abs_out_own_feat,max_abs_out_ref_feat,ref_out_norm\n";
    for (int i = 0; i < N; ++i) {
        Vector6d q;
        for (int j = 0; j < 6; ++j) q[j] = Q.data[(size_t)i * 6 + j];
        const auto f = features(q, T.data[i], t_isl0);
        Eigen::Matrix<double, kFeat, 1> fr;
        for (int j = 0; j < kFeat; ++j) fr[j] = Fref.data[(size_t)i * kFeat + j];
        double ef = 0.0;
        for (int j = 0; j < kFeat; ++j) ef = std::max(ef, std::abs(f[j] - fr[j]));
        const auto yo = mlp(f);
        const auto yr = mlp(fr);
        double eo = 0.0, er = 0.0, on = 0.0;
        for (int l = 0; l < kOut; ++l) {
            const double oref = Oref.data[(size_t)i * kOut + l];
            eo = std::max(eo, std::abs(yo[l] - oref));
            er = std::max(er, std::abs(yr[l] - oref));
            on = std::max(on, std::abs(oref));
        }
        max_feat = std::max(max_feat, ef);
        max_out_own = std::max(max_out_own, eo);
        max_out_ref = std::max(max_out_ref, er);
        out_scale = std::max(out_scale, on);
        c << i << "," << std::setprecision(17) << ef << "," << eo << "," << er << ","
          << on << "\n";
    }
    std::printf("[AccelNet/Infer] N=%d max|dfeat|=%.3e max|dout|(own feat)=%.3e "
                "max|dout|(ref feat)=%.3e max|out|=%.3e\n",
                N, max_feat, max_out_own, max_out_ref, out_scale);
    EXPECT_LT(max_feat, 1e-12);
    EXPECT_LT(max_out_own, 1e-6);
    EXPECT_LT(max_out_ref, 1e-6);
}

// 2) CPU no-grad / InferenceMode latency and no autograd graph.
TEST(AccelNet, NoGradInferenceModeLatency) {
    const std::string p = learn_file("accel_net_scripted.pt");
    ASSERT_FALSE(p.empty()) << "accel_net_scripted.pt not found";
    torch::set_num_threads(1);
    TorchMlp net(p);
    std::ofstream c(csv_path("accel_net_latency.csv"));
    c << "mode,batch,calls,ms_per_call,us_per_sample,requires_grad,has_graph\n";
    for (int B : {1, 64, 256, 1024, 4096}) {
        Eigen::Matrix<double, Eigen::Dynamic, kFeat> F(B, kFeat);
        for (int i = 0; i < B; ++i) F.row(i) = features(random_q(), random_t()).transpose();
        auto x0 = to_ts64(F);
        auto xg = x0.clone().detach().requires_grad_(true);
        auto xn = x0.clone().detach();
        auto bench = [&](const char *mode, int reps, bool nograd_mode,
                         bool inference_mode, const torch::Tensor &inp) {
            for (int w = 0; w < 3; ++w) {
                if (inference_mode) {
                    c10::InferenceMode im(true);
                    net.ts(inp, false);
                } else if (nograd_mode) {
                    torch::NoGradGuard ng;
                    net.ts(inp, false);
                } else {
                    net.ts(inp, false);
                }
            }
            auto t0 = std::chrono::steady_clock::now();
            bool req = false, graph = false;
            for (int r = 0; r < reps; ++r) {
                torch::Tensor y;
                if (inference_mode) {
                    c10::InferenceMode im(true);
                    y = net.ts(inp, false);
                } else if (nograd_mode) {
                    torch::NoGradGuard ng;
                    y = net.ts(inp, false);
                } else {
                    y = net.ts(inp, false);
                }
                req = y.requires_grad();
                graph = (y.grad_fn() != nullptr);
            }
            auto t1 = std::chrono::steady_clock::now();
            const double ms = std::chrono::duration<double, std::milli>(t1 - t0).count() / reps;
            const double us_pt = ms * 1e3 / std::max(B, 1);
            std::printf("[AccelNet/Lat] %s B=%d reps=%d %.4f ms/call %.4f us/point "
                        "requires_grad=%d graph=%d\n", mode, B, reps, ms, us_pt,
                        (int)req, (int)graph);
            c << mode << "," << B << "," << reps << "," << std::setprecision(17)
              << ms << "," << us_pt << "," << (int)req << "," << (int)graph << "\n";
            return std::pair<bool, bool>{req, graph};
        };
        const int reps = std::max(4, 256 / B);
        const auto rg = bench("grad", reps, false, false, xg);
        const auto rn = bench("nograd", reps, true, false, xn);
        const auto ri = bench("inference", reps, false, true, xn);
        EXPECT_TRUE(rg.first);
        EXPECT_FALSE(rn.first);
        EXPECT_FALSE(rn.second);
        EXPECT_FALSE(ri.first);
        EXPECT_FALSE(ri.second);
    }
    std::printf("[AccelNet/Lat] field CPU ref (accel_net_latency_cpu.csv): "
                "B=1 18.85 us/call; B=64 0.605; B=1024 0.0965; B=4096 0.0672 us/point\n");
}

// 3) QOE perturbations within position <=10 m and velocity <=0.1 m/s:
//    measured p99.9 gate + no isolated jump relative to p99.9.
TEST(AccelNet, PerturbationRobustness) {
    const std::string wp = learn_file("accel_net_weights.npz");
    const std::string rp = learn_file("accel_net_ref.npz");
    ASSERT_FALSE(wp.empty());
    ASSERT_FALSE(rp.empty());
    MlpWeights mlp;
    ASSERT_NO_THROW(mlp = MlpWeights(wp));
    NpzReader ref(rp);
    const auto &Q = ref.at("q"), &T = ref.at("t_abs");
    const auto bases = to_v6(Q);
    const int per = 32;
    std::vector<double> dgs, lips, rels;
    double max_dg = 0.0, max_dr = 0.0, max_dv = 0.0;
    std::ofstream c(csv_path("accel_net_perturb.csv"));
    c << "base,sample,dr_m,dv_ms,abs_dg,rel_g,lip\n";
    for (int bi = 0; bi < (int)bases.size(); ++bi) {
        const Vector6d q = bases[(size_t)bi];
        std::vector<double> Jflat;
        noeOsc2rvJacBatch({q}, 1, Jflat);
        Eigen::Matrix<double, 6, 6> J;
        for (int a = 0; a < 6; ++a)
            for (int j = 0; j < 6; ++j) J(a, j) = Jflat[(size_t)a * 6 + j];
        const auto g = mlp(features(q, T.data[bi]));
        const double gn = std::max(g.norm(), 1e-300);
        for (int s = 0; s < per; ++s) {
            Eigen::Matrix<double, 6, 1> drv;
            Eigen::Vector3d dr, dv;
            for (int a = 0; a < 3; ++a) {
                dr[a] = (uni(rng) - 0.5) * 2.0;
                dv[a] = (uni(rng) - 0.5) * 2.0;
            }
            dr *= 10.0 * uni(rng) / std::max(dr.norm(), 1e-300);
            dv *= 0.1 * uni(rng) / std::max(dv.norm(), 1e-300);
            drv << dr, dv;
            const Eigen::Matrix<double, 6, 1> dq = J.ldlt().solve(drv);
            const Vector6d qp = q + dq;
            const auto gp = mlp(features(qp, T.data[bi]));
            const double dg = (gp - g).norm();
            const double rv = std::sqrt(dr.squaredNorm() + dv.squaredNorm());
            dgs.push_back(dg);
            lips.push_back(dg / std::max(rv, 1e-300));
            rels.push_back(dg / gn);
            max_dg = std::max(max_dg, dg);
            max_dr = std::max(max_dr, dr.norm());
            max_dv = std::max(max_dv, dv.norm());
            c << bi << "," << s << "," << std::setprecision(17) << dr.norm() << ","
              << dv.norm() << "," << dg << "," << dg / gn << ","
              << dg / std::max(rv, 1e-300) << "\n";
        }
    }
    const double p999_dg = pct(dgs, 0.999), p999_lip = pct(lips, 0.999);
    const double max_lip = *std::max_element(lips.begin(), lips.end());
    const double max_rel = *std::max_element(rels.begin(), rels.end());
    std::printf("[AccelNet/Pert] samples=%zu max|dr|=%.3f m max|dv|=%.4f m/s "
                "|dg| median=%.3e p99.9=%.3e max=%.3e rel_max=%.3e "
                "Lip median=%.3e p99.9=%.3e max=%.3e\n",
                dgs.size(), max_dr, max_dv, pct(dgs, 0.5), p999_dg, max_dg, max_rel,
                pct(lips, 0.5), p999_lip, max_lip);
    EXPECT_LE(max_dr, 10.0 + 1e-9);
    EXPECT_LE(max_dv, 0.1 + 1e-12);
    EXPECT_TRUE(std::isfinite(max_dg));
    EXPECT_GT(p999_dg, 0.0);
    // Measured gate over the reference state domain (128 states x 32):
    // p99.9(|dg|) ~ 3.0e-9 m/s^2, ~6% of the max |out| = 5.2e-8; 1e-8 is 3.3x
    // the measured p99.9. "No isolated jump" = max within 100x p99.9.
    EXPECT_LT(p999_dg, 1e-8);
    EXPECT_LE(max_dg, 100.0 * p999_dg);
    EXPECT_GT(p999_lip, 0.0);
    EXPECT_LT(p999_lip, 1e-9);
    EXPECT_LE(max_lip, 100.0 * p999_lip);
}

// 4) GVE RHS against the stable reference:
//    qdot_base = gveRhsField(q,t,beta) and qdot_field = qdot_base + W @ a_field
//    with W = gveGaussW (ECI control matrix, no RTN projection).
TEST(AccelNet, GveRhsReference) {
    const std::string gp = learn_file("accel_net_gve_ref.npz");
    const std::string dp = project_root() + "/data/drag_model_a521.npz";
    const std::string wp = learn_file("accel_net_weights.npz");
    ASSERT_FALSE(gp.empty()) << "accel_net_gve_ref.npz not found";
    ASSERT_TRUE(std::filesystem::exists(dp)) << "drag_model_a521.npz not found";
    ASSERT_FALSE(wp.empty());
    NpzReader ref(gp), drag(dp);
    const auto qv = to_v6(ref.at("q"));
    const auto tovec = [](const NpzArray &a) {
        return std::vector<double>(a.data.begin(), a.data.end());
    };
    const std::vector<double> t = tovec(ref.at("t_abs")), beta = tovec(ref.at("beta"));
    const std::vector<double> a_field = tovec(ref.at("a_field"));
    const std::vector<double> qdot_base_ref = tovec(ref.at("qdot_base"));
    const std::vector<double> qdot_field_ref = tovec(ref.at("qdot_field"));
    const std::vector<double> W_ref = tovec(ref.at("W"));
    const int N = (int)qv.size();
    ASSERT_EQ((int)t.size(), N);
    ASSERT_EQ((int)beta.size(), N);
    ASSERT_EQ((int)W_ref.size(), 18 * N);

    // Same known model as script/learn/train_learn_theta.setup_known_model.
    const auto &Rho = drag.at("rho");
    const std::vector<double> rho = tovec(Rho);
    const double h_lo = drag.at("h_lo").data[0], h_hi = drag.at("h_hi").data[0];
    std::vector<double> beta_all;
    if (drag.has("beta_fit_all")) beta_all = tovec(drag.at("beta_fit_all"));
    ASSERT_NO_THROW(kep3::setDragTable(h_lo, h_hi, rho, beta_all));
    kep3::clearDragField();
    kep3::setThirdBodyCuda(false);
    kep3::setSrpCuda(false);

    std::vector<double> base, W;
    ASSERT_NO_THROW(kep3::gveRhsFieldBatch(qv, t, beta, base));
    ASSERT_NO_THROW(kep3::gveGaussWBatch(qv, W));
    ASSERT_EQ((int)base.size(), 6 * N);
    ASSERT_EQ((int)W.size(), 18 * N);

    MlpWeights mlp(wp);
    double max_base = 0.0, max_W = 0.0, max_recomp = 0.0, max_a = 0.0, scale = 0.0;
    std::ofstream c(csv_path("accel_net_gve.csv"));
    c << "sample,max_abs_base_err,max_abs_W_err,max_abs_recomposed_err,abs_qdot_field\n";
    for (int i = 0; i < N; ++i) {
        // a_field must be exactly the exported network output on (q,t).
        Vector6d q = qv[(size_t)i];
        const auto a_mlp = mlp(features(q, t[(size_t)i]));
        double ea = 0.0;
        for (int l = 0; l < 3; ++l)
            ea = std::max(ea, std::abs(a_mlp[l] - a_field[(size_t)i * 3 + l]));
        max_a = std::max(max_a, ea);
        double eb = 0.0, ew = 0.0, er = 0.0, on = 0.0;
        for (int cix = 0; cix < 6; ++cix) {
            eb = std::max(eb, std::abs(base[(size_t)i * 6 + cix] -
                                        qdot_base_ref[(size_t)i * 6 + cix]));
            on = std::max(on, std::abs(qdot_field_ref[(size_t)i * 6 + cix]));
            double rec = base[(size_t)i * 6 + cix];
            for (int a = 0; a < 3; ++a)
                rec += W[((size_t)i * 6 + cix) * 3 + a] * a_field[(size_t)i * 3 + a];
            er = std::max(er, std::abs(rec - qdot_field_ref[(size_t)i * 6 + cix]));
        }
        for (int k = 0; k < 18; ++k)
            ew = std::max(ew, std::abs(W[(size_t)i * 18 + k] - W_ref[(size_t)i * 18 + k]));
        max_base = std::max(max_base, eb);
        max_W = std::max(max_W, ew);
        max_recomp = std::max(max_recomp, er);
        scale = std::max(scale, on);
        c << i << "," << std::setprecision(17) << eb << "," << ew << "," << er << ","
          << on << "\n";
    }
    std::printf("[AccelNet/GVE] N=%d max|dqdot_base|=%.3e max|dW|=%.3e "
                "max|d(qdot_base+W a_field)|=%.3e max|d a_field|=%.3e "
                "max|qdot_field|=%.3e (direct ECI, W=gveGaussW, no RTN)\n",
                N, max_base, max_W, max_recomp, max_a, scale);
    EXPECT_LT(max_a, 1e-6);
    EXPECT_LT(max_base, 1e-9);
    EXPECT_LT(max_W, 1e-9);
    EXPECT_LT(max_recomp, 1e-9);
    kep3::clearDragTable();
}

// 5) Single-frame ISL reference: d / dobs-consistent residual / cost / grad.
TEST(AccelNet, IslReference) {
    const std::string p = learn_file("accel_net_isl_ref.npz");
    ASSERT_FALSE(p.empty()) << "accel_net_isl_ref.npz not found";
    NpzReader ref(p);
    const auto q = to_v6(ref.at("q"));
    const auto &E = ref.at("edges"), &D = ref.at("d"), &Dobs = ref.at("dobs"),
               &R = ref.at("residual"), &G = ref.at("grad");
    const int ns = (int)q.size(), ne = (int)E.dim(0);
    ASSERT_EQ(ns, 4);
    ASSERT_EQ(ne, 4);
    std::vector<double> rv, J;
    noeOsc2rvBatch(q, 16, rv);
    noeOsc2rvJacBatch(q, 16, J);
    std::vector<Eigen::Vector3d> pos((size_t)ns);
    for (int i = 0; i < ns; ++i)
        for (int a = 0; a < 3; ++a) pos[(size_t)i][a] = rv[(size_t)i * 6 + a];
    double max_d = 0.0, max_res = 0.0, max_cost = 0.0, max_grad = 0.0, grad_scale = 0.0;
    double cost = 0.0;
    std::vector<Eigen::Matrix<double, 6, 1>> grad((size_t)ns,
                                                  Eigen::Matrix<double, 6, 1>::Zero());
    std::ofstream c(csv_path("accel_net_isl_ref.csv"));
    c << "edge,d,d_ref,residual,residual_ref,dobs\n";
    for (int e = 0; e < ne; ++e) {
        const int i = (int)E.data[(size_t)e * 2], j = (int)E.data[(size_t)e * 2 + 1];
        const double d = (pos[(size_t)i] - pos[(size_t)j]).norm();
        const double dobs = Dobs.data[e];
        const double r = d - dobs;
        cost += r * r;
        max_d = std::max(max_d, std::abs(d - D.data[e]));
        max_res = std::max(max_res, std::abs(r - R.data[e]));
        const Eigen::Vector3d u = (pos[(size_t)i] - pos[(size_t)j]) / std::max(d, 1e-30);
        for (int k = 0; k < 6; ++k) {
            const double dpi = J[(size_t)i * 36 + 0 * 6 + k] * u[0] +
                               J[(size_t)i * 36 + 1 * 6 + k] * u[1] +
                               J[(size_t)i * 36 + 2 * 6 + k] * u[2];
            const double dpj = J[(size_t)j * 36 + 0 * 6 + k] * u[0] +
                               J[(size_t)j * 36 + 1 * 6 + k] * u[1] +
                               J[(size_t)j * 36 + 2 * 6 + k] * u[2];
            grad[(size_t)i][k] += 2.0 * r * dpi;
            grad[(size_t)j][k] -= 2.0 * r * dpj;
        }
        c << e << "," << std::setprecision(17) << d << "," << D.data[e] << "," << r << ","
          << R.data[e] << "," << dobs << "\n";
    }
    max_cost = std::abs(cost - ref.at("cost").data[0]);
    for (int i = 0; i < ns; ++i)
        for (int k = 0; k < 6; ++k) {
            const double gr = G.data[(size_t)i * 6 + k];
            max_grad = std::max(max_grad, std::abs(grad[(size_t)i][k] - gr));
            grad_scale = std::max(grad_scale, std::abs(gr));
        }
    std::printf("[AccelNet/ISLref] stars=%d edges=%d max|dd|=%.3e max|dres|=%.3e "
                "cost=%.9f dcost=%.3e grad_scale=%.3e max|dgrad|=%.3e (rel=%.3e)\n",
                ns, ne, max_d, max_res, cost, max_cost, grad_scale, max_grad,
                max_grad / std::max(grad_scale, 1e-300));
    EXPECT_LT(max_d, 1e-9);
    EXPECT_LT(max_res, 1e-9);
    EXPECT_LT(max_cost, 1e-9);
    // grad ~1e8 (m^2 scale): absolute 1e-5 is ~1e-13 relative, i.e. the
    // exported assembly and this one agree to round-off of the same DA Jp.
    EXPECT_LT(max_grad / std::max(grad_scale, 1e-300), 1e-12);
    EXPECT_LT(max_grad, 1e-5);
}

// 6) Small 4-star ISL optimization with one fixed TorchScript module.
TEST(AccelNet, IslFieldOptimization) {
    const std::string p = learn_file("accel_net_scripted.pt");
    ASSERT_FALSE(p.empty()) << "accel_net_scripted.pt not found";
    torch::set_num_threads(1);
    TorchMlp net(p);
    const auto qb = data_qoe();
    const int N = 4, L = 4, E = 6;
    const double dt = 180.0;
    // Truth trajectory with the network field: q_{k+1}=q_k+dt*B*a(q_k,t_k),
    // B maps ECI acceleration to the QOE velocity-like rows; synthetic
    // linearized ISL p=Jp q with Jp from the DA Jacobian at the base state.
    auto Bmat = torch::zeros({N, 6, 3}, torch::TensorOptions().dtype(torch::kFloat64));
    for (int i = 0; i < N; ++i) {
        Bmat[i][3][0] = 1.0; Bmat[i][4][1] = 1.0; Bmat[i][5][2] = 1.0;
    }
    std::vector<double> Jall;
    noeOsc2rvJacBatch(std::vector<Vector6d>(qb.begin(), qb.begin() + N), 4, Jall);
    auto Jpt = torch::zeros({N, 3, 6}, torch::TensorOptions().dtype(torch::kFloat64));
    for (int i = 0; i < N; ++i)
        for (int a = 0; a < 3; ++a)
            for (int cix = 0; cix < 6; ++cix) Jpt[i][a][cix] = Jall[(size_t)i * 36 + a * 6 + cix];
    auto q0_true = torch::zeros({N, 6}, torch::TensorOptions().dtype(torch::kFloat64));
    for (int i = 0; i < N; ++i)
        for (int cix = 0; cix < 6; ++cix) q0_true[i][cix] = qb[i][cix];
    int ei[E], ej[E];
    int e = 0;
    for (int i = 0; i < N; ++i)
        for (int j = i + 1; j < N; ++j) { ei[e] = i; ej[e] = j; ++e; }
    auto traj = [&](torch::Tensor q0, bool grad) {
        std::vector<torch::Tensor> qs;
        auto q = q0;
        for (int k = 0; k < L; ++k) {
            qs.push_back(q);
            auto t = torch::tensor(kTIsl0 + k * dt, torch::TensorOptions().dtype(torch::kFloat64));
            auto f = torch_features(q, t);
            torch::Tensor a;
            if (grad) a = net.ts(f, false);
            else {
                torch::NoGradGuard ng;
                a = net.ts(f, true);
            }
            q = q + dt * torch::bmm(Bmat, a.unsqueeze(2)).squeeze(2);
        }
        return qs;
    };
    auto pos = [&](const torch::Tensor &q) {
        return torch::bmm(Jpt, q.unsqueeze(2)).squeeze(2);   // (N,3)
    };
    auto dists = [&](const std::vector<torch::Tensor> &qs) {
        std::vector<torch::Tensor> ds;
        for (int k = 0; k < L; ++k) {
            auto p = pos(qs[k]);
            for (int ee = 0; ee < E; ++ee)
                ds.push_back(torch::norm(p[ei[ee]] - p[ej[ee]]));
        }
        return torch::stack(ds);
    };
    const auto qs_true = traj(q0_true, false);
    const auto d_true = dists(qs_true);
    torch::manual_seed(7);
    const auto noise = 0.1 * torch::randn_like(d_true);
    const auto d_obs = d_true + noise;
    // Optimize q0 from a perturbed start; the module is built once (above).
    auto q0v = q0_true.clone();
    q0v.data_ptr<double>()[0] += 1.0;
    q0v.data_ptr<double>()[6 + 1] += 1.0e-6;
    q0v.data_ptr<double>()[12 + 2] += 1.0e-6;
    q0v.set_requires_grad(true);
    torch::optim::Adam opt({q0v}, torch::optim::AdamOptions(1e-8));
    double first = 0.0, last = 0.0;
    bool finite = true;
    std::ofstream c(csv_path("accel_net_isl.csv"));
    c << "iter,loss,grad_norm\n";
    for (int it = 0; it < 50; ++it) {
        opt.zero_grad();
        auto qs = traj(q0v, true);
        auto d = dists(qs);
        auto loss = torch::mean(torch::pow(d - d_obs, 2));
        loss.backward();
        auto gnorm = q0v.grad().norm();
        if (!std::isfinite(loss.item<double>()) || !std::isfinite(gnorm.item<double>()))
            finite = false;
        if (it == 0) first = loss.item<double>();
        last = loss.item<double>();
        std::printf("[AccelNet/ISL] it=%d loss=%.6e grad_norm=%.3e\n", it, last,
                    gnorm.item<double>());
        c << it << "," << std::setprecision(17) << last << ","
          << gnorm.item<double>() << "\n";
        opt.step();
    }
    std::printf("[AccelNet/ISL] fixed-module loop: first=%.6e last=%.6e finite=%d "
                "(synthetic linearized ISL with ECI field in QOE dyn)\n",
                first, last, (int)finite);
    EXPECT_TRUE(finite);
    EXPECT_LT(last, first);
}
